'use client';
// Mounted only into an isolated test container; no production route or authentication bypass.
import {useRef,useState,useSyncExternalStore} from 'react';import {createNotifications} from '../../../../shared/notifications.mjs';import Notifications from '../components/elements/notifications';
export default function Page(){const clock=useRef(0),[store]=useState(()=>createNotifications({now:()=>clock.current,queueCapacity:2})),state=useSyncExternalStore(store.subscribe,store.getSnapshot,store.getSnapshot),origin=useRef<HTMLButtonElement>(null),sequence=useRef(0);return <main><h1>Notification clock fixture</h1><button ref={origin} onClick={()=>store.push({title:'Keyed',message:'Original content',key:'same'})}>Keyed</button><button onClick={()=>store.push({title:'Changed',message:'Changed content',key:'same'})}>Merge changed</button><button onClick={()=>store.push({title:`Item ${++sequence.current}`,message:'Synthetic content'})}>Unique</button><button onClick={()=>{for(let i=0;i<8;i++)store.push({title:`Item ${++sequence.current}`,message:'Synthetic content'});}}>Burst</button><button onClick={()=>store.push({title:'Long',message:'Long synthetic content '.repeat(150)})}>Long</button><button data-advance="1000" onClick={()=>{clock.current+=1000;store.tick();}}>Advance 1000</button><button data-advance="15000" onClick={()=>{clock.current+=15000;store.tick();}}>Advance 15000</button><button onClick={()=>store.clear()}>Clear</button><button onClick={()=>store.end()}>End</button><output aria-label="queue snapshot">{JSON.stringify({waiting:state.waiting.map(x=>({title:x.title,count:x.count,remainingMs:x.remainingMs})),suspended:state.suspended.map(x=>({title:x.title,remainingMs:x.remainingMs})),omitted:state.omitted,ended:state.ended})}</output><Notifications store={store} desktopVisible={3} narrowVisible={1} returnFocus={()=>origin.current}/></main>;}
